#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

const int MAX=33,MOD=1000000007;

struct Mat {
    long long mat[MAX][MAX];
};

Mat mat_mult(const Mat &m1, const Mat &m2, int size) {
    Mat res = {};
    for (int i=0; i<=size; ++i)
        for (int j=0; j<=size; ++j) {
            res.mat[i][j]=0;
            for (int p=0; p<=size; ++p)
                res.mat[i][j]=(res.mat[i][j]+m1.mat[i][p]*m2.mat[p][j])%MOD;
        }
    return res;
}

int main() {
    long long n;
    int k;
    cin >> n >> k;

    Mat answer = {};
    for (int i=0; i<=k; ++i)
        answer.mat[i][i]=1;

    vector<Mat> transition(k);
    for (int p=0; p<k; ++p) {
        for (int i=0; i<=k; ++i)
            for (int j=0; j<=k; ++j)
                transition[p].mat[i][j]= (i==j || i==p) ? 1 : 0;
    }

    vector<int> bits;
    for (long long temp=n; temp>0; temp/=k)
        bits.push_back(temp%k);
    bits.push_back(0);
    partial_sum(bits.rbegin(), bits.rend(), bits.rbegin());

    for (size_t p=0; p+1<bits.size(); ++p) {
        for (int i=bits[p]-1; i>=bits[p+1]; --i)
            answer=mat_mult(transition[i%k], answer, k);
        vector<Mat> pre(k), suf(k);
        pre[0]=transition[0];
        for (int i=1; i<k; ++i)
            pre[i]=mat_mult(pre[i-1], transition[i], k);
        suf[k-1]=transition[k-1];
        for (int i=k-2; i>=0; --i)
            suf[i]=mat_mult(transition[i], suf[i+1], k);
        answer=mat_mult(suf[0], answer, k);
        for (int i=1; i<k; ++i)
            answer=mat_mult(suf[i], pre[i-1], k);
    }

    long long total=0;
    for (int i=0; i<=k; ++i)
        total+=answer.mat[i][k];
    cout << total%MOD << endl;
    return 0;
}
